    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    # Merge intervals in a
    a_sorted = sorted(a)
    a_merged = []
    for start, end in a_sorted:
        if a_merged and a_merged[-1][1] >= start:
            a_merged[-1][1] = max(a_merged[-1][1], end)
        else:
            a_merged.append([start, end])

    # Merge intervals in b
    b_sorted = sorted(b)
    b_merged = []
    for start, end in b_sorted:
        if b_merged and b_merged[-1][1] >= start:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current = [a_start, a_end]

        for b_start, b_end in b_merged:
            if current[1] <= b_start or current[0] >= b_end:
                # No overlap
                continue

            if current[0] < b_start:
                # Part before b
                result.append([current[0], b_start])

            if current[1] > b_end:
                # Part after b
                current[0] = b_end
            else:
                # Completely covered by b
                current[0] = current[1]
                break

        if current[0] < current[1]:
            result.append(current)

    # Merge touching intervals in result
    if not result:
        return []

